/**
 * The terminal dashboard on #/processing, driven by a REAL snapshot.
 *
 * `console-mirror.fixture.json` is generated by roop/terminal_dashboard.py itself (a TerminalProgressManager fed the
 * calls the pipeline makes - stage_telemetry enter/progress/retire/record_op, the S1/S4 hooks - on a fixed clock): the
 * `running` and `final` snapshots are what `/ws/telemetry` carries under `dashboard`, and `console` is the text the
 * backend painted from the SAME running snapshot. So what is checked is the claim the feature makes - the React screen
 * and the terminal show identical numbers - and the path a browser takes:
 *
 *   frame -> setDashboardTelemetry -> useTelemetryStore -> ConsoleMirror -> text
 *
 *   * every number the console printed (percent, counts, rate, ETA countdown, the seven latency cells, the bottleneck
 *     tag, the hit rates, VRAM) appears, as the same text, on the screen;
 *   * the bottleneck column - and only that one - is flagged;
 *   * a figure the backend did not measure is an em dash, never 0;
 *   * a stage that ended short says so instead of reading 100%;
 *   * idle renders nothing; a frame without a dashboard cannot clear one; a finished job stays readable.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

globalThis.window = globalThis;

const here = dirname(fileURLToPath(import.meta.url));
const fx = JSON.parse(readFileSync(join(here, 'console-mirror.fixture.json'), 'utf8'));

const React = (await import('react')).default;
const { renderToStaticMarkup } = await import('react-dom/server');
const M = await import('../src/components/faceswap/dashboardModel.js');
const { default: ConsoleMirror, ConsoleMirrorView } = await import('../src/components/faceswap/ConsoleMirror.jsx');
const store = await import('../src/store/telemetryStore.js');

let failures = 0;
const ok = (name, cond, detail = '') => {
  if (cond) { console.log(`  PASS  ${name}`); return; }
  failures += 1;
  console.log(`  FAIL  ${name}${detail ? `\n          ${detail}` : ''}`);
};
const html = (el) => renderToStaticMarkup(el).replace(/<!-- -->/g, '');
const text = (h) => h.replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ');
const clone = (o) => JSON.parse(JSON.stringify(o));

const run = fx.running;
const consoleStage = fx.console.stage_lines.join('\n');
const consoleTel = fx.console.telemetry_lines.join('\n');
const rows = Object.fromEntries(M.stageRows(run).map((r) => [r.id, r]));

// ── the formatters, against the console's own examples ───────────────────────
ok('durations are the console\'s', M.fmtDur(74) === '01m 14s' && M.fmtDur(3725) === '1h 02m 05s' && M.fmtDur(0) === '00m 00s');
ok('an unmeasured duration is an em dash', M.fmtDur(null) === '—' && M.fmtDur(undefined) === '—' && M.fmtDur(NaN) === '—');
{
  const base = new Date(2026, 9, 28, 3, 22, 56).getTime() / 1000;
  ok('countdown -> wall-clock finish, to the second', M.fmtEta(74, base + 74, base) === '01m 14s -> 03:24:10', M.fmtEta(74, base + 74, base));
  const late = new Date(2026, 9, 28, 23, 50, 0).getTime() / 1000;
  ok('a finish on another day says so', M.fmtEta(1800, late + 1800, late).includes('(+1d)'), M.fmtEta(1800, late + 1800, late));
  ok('no rate yet -> a dash', M.fmtEta(null, null, base) === '—');
}

// ── every stage line of the console, on the screen ───────────────────────────
ok('four stages, in order', Object.keys(rows).join() === 'S1,S2,S3,S4', Object.keys(rows).join());
const s3 = run.stages.S3;
ok('S3 percent is the console\'s', rows.S3.pctText === '16.7%' && consoleStage.includes(rows.S3.pctText), rows.S3.pctText);
ok('S3 counts are the console\'s', rows.S3.counts === '300/1,800 frames' && consoleStage.includes(rows.S3.counts), rows.S3.counts);
ok('S3 rate is the console\'s', rows.S3.note.includes(`${s3.rate.toFixed(1)} fps`) && consoleStage.includes(`${s3.rate.toFixed(1)} fps`), rows.S3.note);
{
  const countdown = rows.S3.status.replace(/ -> .*/, '');                       // the clock half is local-time; compared below
  ok('S3 ETA countdown is the console\'s', countdown === 'ETA: 00m 30s' && consoleStage.includes(countdown), rows.S3.status);
  const clock = rows.S3.status.split(' -> ')[1];
  ok('S3 ETA finish is the snapshot\'s eta_at in local time', clock === M.fmtClock(s3.eta_at, run.updated_at).replace(/ \(\+\d+d\)$/, ''), clock);
}
ok('S3 says what its frames are (writer-accepted)', rows.S3.note.includes('basis retired'));
ok('S2 carries scene cuts and the face-free bypass share',
  rows.S2.note.includes('cuts 7') && rows.S2.note.includes('face-free 25.0%') && consoleStage.includes('cuts 7') && consoleStage.includes('face-free 25.0%'), rows.S2.note);
ok('S1 is done with its steps', rows.S1.state === 'DONE' && rows.S1.pctText === '100.0%' && rows.S1.note.includes('media probe'));
ok('S4 is pending before the finalize', rows.S4.state === 'PENDING' && rows.S4.counts === '' && rows.S4.status === 'pending');

// ── latency split, bottleneck, hit rates ─────────────────────────────────────
const cells = M.latencyCells(run);
ok('seven latency cells in the brief\'s order',
  cells.map((c) => c.label).join('|') === 'Decode|Detect|Swap|Mask/Parse|Restore|Color/Blend|Encode', cells.map((c) => c.label).join('|'));
ok('each cell shows the console\'s milliseconds',
  cells.every((c) => consoleTel.includes(`${c.label} ${c.ms}`)), cells.map((c) => `${c.label} ${c.ms}`).join(' | '));
ok('exactly the bottleneck column is flagged', cells.filter((c) => c.bottleneck).map((c) => c.key).join() === 'restore'
  && cells.find((c) => c.key === 'restore').severity === 'yellow');
ok('the bottleneck tag is the console\'s', M.bottleneckText(run) === '[BOTTLENECK: Restore 54%]' && consoleTel.includes(M.bottleneckText(run)), M.bottleneckText(run));
{
  const h = Object.fromEntries(M.hitRateCells(run).map((c) => [c.key, c.value]));
  ok('Smart-Skip ROI reuse is the console\'s', h.roi === '10.0%' && consoleTel.includes(`Smart-Skip ROI reused ${h.roi}`), h.roi);
  ok('Stage-2 face-free share is the console\'s', h.facefree === '25.0%' && consoleTel.includes(`face-free skipped ${h.facefree}`), h.facefree);
  ok('VRAM allocated / peak are the console\'s', h.vram === '7.25 / 8.50 GB' && consoleTel.includes('VRAM 7.25 / peak 8.50 GB'), h.vram);
}
{
  const red = clone(run);
  red.telemetry.bottleneck = { stage: 'restore', label: 'Restore', share_pct: 64, severity: 'red' };
  ok('a 64% bottleneck is flagged red', M.latencyCells(red).find((c) => c.bottleneck).severity === 'red'
    && M.bottleneckText(red) === '[BOTTLENECK: Restore 64%]');
}

// ── unmeasured stays unmeasured ──────────────────────────────────────────────
{
  const blank = clone(run);
  blank.telemetry.latency_ms = Object.fromEntries(Object.keys(blank.telemetry.latency_ms).map((k) => [k, null]));
  blank.telemetry.bottleneck = null;
  blank.telemetry.hit_rates = { smart_skip_roi_reused_pct: null, smart_skip_enabled: false, stage2_face_free_skipped_pct: null, vram_allocated_gb: null, vram_peak_gb: null };
  ok('no frames yet -> dashes in every latency cell, never 0', M.latencyCells(blank).every((c) => c.ms === '—'));
  ok('no bottleneck yet says so', M.bottleneckText(blank) === '[bottleneck: measuring]');
  const hit = Object.fromEntries(M.hitRateCells(blank).map((c) => [c.key, c.value]));
  ok('Smart-Skip switched off reads "off", an unmeasured share a dash',
    hit.roi === 'off' && hit.facefree === '—%' && hit.vram === '— / — GB', JSON.stringify(hit));
}

// ── a stage that ended short is not rounded to 100% ──────────────────────────
{
  const short = clone(fx.final);
  Object.assign(short.stages.S3, { pct: 50, done: 900, total: 1800, state: 'DONE' });
  short.stages.S3.detail.short_by = 900;
  const row = M.stageRows(short).find((r) => r.id === 'S3');
  ok('a short stage shows its true percent and says SHORT', row.pctText === '50.0%' && row.note.includes('SHORT by 900 frames'), row.note);
}
{
  const paused = clone(run);
  paused.stages.S3.paused = true;
  ok('a paused stage says PAUSED instead of a stale ETA', M.stageRows(paused).find((r) => r.id === 'S3').status === 'PAUSED');
}

// ── the component ────────────────────────────────────────────────────────────
{
  const h = html(React.createElement(ConsoleMirrorView, { dash: run }));
  const t = text(h);
  ok('the mirror renders the running job', h.includes('data-testid="console-mirror"') && h.includes('data-active="true"'));
  ok('one progressbar per stage with its percent', (h.match(/role="progressbar"/g) || []).length === 4 && h.includes('aria-valuenow="17"'));
  ok('the three-way job label (mode, queue position, file)', t.includes('SEGMENTED') && t.includes('queue 3/8') && t.includes('clip.mp4'), t);
  ok('exactly one latency cell is marked as the bottleneck', (h.match(/data-bottleneck="true"/g) || []).length === 1
    && /data-col="restore" data-bottleneck="true"/.test(h));
  ok('every console number is in the markup', ['16.7%', '300/1,800 frames', 'ETA: 00m 30s', 'Restore 32.0', '[BOTTLENECK: Restore 54%]', '10.0%', '7.25 / 8.50 GB']
    .every((s) => t.includes(s)), t);
  ok('state is words, not colour alone', ['S1 Probe', 'S2 Pre-scan', 'S3 Swap', 'S4 Finalize', 'done', 'pending'].every((s) => t.includes(s)));
  ok('no NaN / undefined / [object] anywhere', !/NaN|undefined|\[object/.test(h));
}
ok('idle renders nothing', html(React.createElement(ConsoleMirrorView, { dash: fx.idle })) === ''
  && html(React.createElement(ConsoleMirrorView, { dash: undefined })) === '');
{
  const h = html(React.createElement(ConsoleMirrorView, { dash: fx.final }));
  const t = text(h);
  ok('a finished job stays on screen, marked as the last run', h.includes('data-active="false"') && t.includes('last run'));
  ok('the finished S4 is done, with its steps', t.includes('S4 Finalize') && t.includes('segment custody & concat, audio remux, output verification'), t);
}

// ── the store path ───────────────────────────────────────────────────────────
{
  const get = () => store.useTelemetryStore.getState().dashboard;
  ok('the store starts idle', get().active === false && !get().stages);
  store.setDashboardTelemetry({ event: 'progress', processing: true });
  ok('a frame without a dashboard (older backend) changes nothing', get().active === false);
  store.setDashboardTelemetry({ event: 'progress', dashboard: run });
  ok('a frame with one replaces it', get().stages?.S3?.done === 300);
  const before = get();
  store.setDashboardTelemetry({ event: 'progress', dashboard: clone(run) });
  ok('an identical frame keeps the same object (no re-render)', get() === before);
  store.setDashboardTelemetry({ event: 'progress', processing: true });
  ok('a later frame without one cannot clear it', get().stages?.S3?.done === 300);
  // zustand answers a server render with the store's INITIAL state (see render-pipeline-report.mjs), so the connected
  // adapter cannot be read back here; what it does is hand `getState().dashboard` to the view, which is rendered below.
  ok('ConsoleMirror is exported as the store adapter', typeof ConsoleMirror === 'function');
  const viaStore = html(React.createElement(ConsoleMirrorView, { dash: get() }));
  ok('what the store holds renders as the screen', viaStore.includes('data-testid="console-mirror"') && text(viaStore).includes('300/1,800 frames'));
  store.setDashboardTelemetry({ dashboard: fx.final });
  ok("the next job's end state replaces it", text(html(React.createElement(ConsoleMirrorView, { dash: get() }))).includes('last run'));
}

console.log(failures === 0 ? '\nconsole mirror: all checks passed' : `\nconsole mirror: ${failures} FAILED`);
globalThis.__RENDER_CHECK_FAILURES__ = failures;
